action.code:
float sx = 2.0f * u.x - 1.0f;
float sy = 2.0f * u.y - 1.0f;
if (sx == 0.0f && sy == 0.0f) return Point2f(0.0f, 0.0f);
float r, theta;
if (std::abs(sx) > std::abs(sy)) {
    r = sx;
    theta = std::numbers::pi_v<float> / 4.0f * (sy / sx);
} else {
    r = sy;
    theta = std::numbers::pi_v<float> / 2.0f - std::numbers::pi_v<float> / 4.0f * (sx / sy);
}
return Point2f(r * std::cos(theta), r * std::sin(theta));

